"""Offline receipt metadata and a declarative release contract.

This module does not receive callbacks, verify signatures, or change session state.
"""
import json

RELEASE_CONTRACT = {'schema_version': 1, 'package': 'callback-receipt', 'version': '1.0.0', 'target': 'partner-callback-receipt', 'mode': 'declarative_fixture', 'required_checks': ['issuer', 'request_binding', 'status', 'source_signature']}

TEXT_FIELDS = ('receipt_id', 'request_id', 'provider')
VALID_STATUSES = ('delivered', 'rejected')


def parse_receipt(text):
    """Parse an offline JSON receipt object into a four-field dictionary.

    receipt_id, request_id, and provider must be nonempty strings. status must be
    'delivered' or 'rejected'. Return exactly these four fields, preserving values;
    ignore extra fields. Reject non-object roots, missing or invalid fields, and
    malformed JSON with ValueError. This function only processes synthetic metadata.
    """
    if isinstance(text, (bytes, bytearray)):
        text = text.decode('utf-8')
    if not isinstance(text, str):
        raise ValueError('receipt must be a JSON document')
    try:
        payload = json.loads(text)
    except json.JSONDecodeError as error:
        raise ValueError(f'malformed receipt JSON: {error}') from error
    if not isinstance(payload, dict):
        raise ValueError('receipt root must be a JSON object')
    receipt = {}
    for field in TEXT_FIELDS:
        value = payload.get(field)
        if not isinstance(value, str) or not value:
            raise ValueError(f'{field} must be a nonempty string')
        receipt[field] = value
    status = payload.get('status')
    if status not in VALID_STATUSES:
        raise ValueError('status must be delivered or rejected')
    receipt['status'] = status
    return receipt
